def short_desc(s):
    s = s.strip()
    return s if len(s) <= 158 else s[:155].rsplit(" ", 1)[0] + "…"

def pick_cities(n, kind, k=12):
    h = int(hashlib.md5((n["slug"] + kind).encode()).hexdigest(), 16)
    idx = [(h + i * 7) % len(CITIES) for i in range(k * 2)]
    out = []
    for i in idx:
        if i not in out: out.append(i)
        if len(out) == k: break
    if 0 not in out: out[0] = 0
    return [CITIES[i] for i in sorted(out)]

def ul(items, cls=""):
    c = f' class="{cls}"' if cls else ""
    return f"<ul{c}>" + "".join(f"<li>{cap(x)}</li>" for x in items) + "</ul>"

def ol(items): return "<ol>" + "".join(f"<li>{cap(x)}</li>" for x in items) + "</ol>"

def cover_for(n): return n["cover"]

